CREATE TABLE media_assets (id UUID PRIMARY KEY, owner_id UUID NOT NULL, status TEXT NOT NULL CHECK(status IN ('quarantined','scanning','ready','rejected')), kind TEXT NOT NULL CHECK(kind IN ('image','video')), safe_url TEXT, thumbnail_url TEXT, duration_seconds INT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE community_comments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),post_id UUID NOT NULL REFERENCES community_posts(id) ON DELETE CASCADE,author_id UUID NOT NULL,parent_id UUID REFERENCES community_comments(id),body TEXT NOT NULL CHECK(char_length(body) BETWEEN 1 AND 1000),moderation_state TEXT NOT NULL DEFAULT 'active' CHECK(moderation_state IN ('active','removed','pending_review')),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ);
CREATE INDEX community_comments_page_idx ON community_comments(post_id,created_at DESC) WHERE deleted_at IS NULL AND moderation_state='active';
CREATE TYPE story_visibility AS ENUM ('network','public');
CREATE TABLE stories (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),author_id UUID NOT NULL,media_id UUID NOT NULL REFERENCES media_assets(id),visibility story_visibility NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),expires_at TIMESTAMPTZ NOT NULL, CHECK(expires_at > created_at AND expires_at <= created_at + interval '24 hours'));
CREATE INDEX stories_expires_idx ON stories(expires_at DESC);
CREATE TABLE story_views (story_id UUID NOT NULL REFERENCES stories(id) ON DELETE CASCADE,viewer_id UUID NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(story_id,viewer_id));
CREATE TABLE story_likes (story_id UUID NOT NULL REFERENCES stories(id) ON DELETE CASCADE,actor_id UUID NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(story_id,actor_id));
